package bench

import (
	"context"
	"fmt"
	"reflect"
	"testing"
	"time"

	d "github.com/gaon000/exchange/internal/domain"
)

func business(seq d.Int, trades d.Int) Outcome {
	return Outcome{Class: Business, HTTPStatus: 200, Code: string(d.Accepted), Certainty: "COMPLETED", CommandSeq: seq, TradeCount: trades, OrderStatus: d.Open, Fingerprint: fmt.Sprintf("%064x", seq)}
}

// Six fixed attempts include a cross-phase retry, an original slower than its
// retry, and a response beyond the fixed observation window. Expected arithmetic
// is hand-calculated rather than generated by the aggregation implementation.
func summaryFixture(t *testing.T) (*Plan, RunResult) {
	s := testSpec()
	s.Rate, s.Warmup, s.Duration, s.Mix = 2, time.Second, 2*time.Second, Mix{Rest: 100}
	p := buildPlan(t, s)
	duplicate := func(at, original int) {
		r := p.requests[original]
		r.Index, r.Phase, r.Scheduled, r.Intent = at, p.requests[at].Phase, p.requests[at].Scheduled, Duplicate
		p.requests[at] = r
	}
	duplicate(2, 0)
	duplicate(4, 3)
	finish := []time.Duration{100 * time.Millisecond, 550 * time.Millisecond, 1050 * time.Millisecond, 2400 * time.Millisecond, 2100 * time.Millisecond, 3200 * time.Millisecond}
	outcomes := []Outcome{business(10, 1), business(11, 0), business(10, 1), business(12, 2), business(12, 2), business(13, 0)}
	result := RunResult{Options: testRunOptions(), Elapsed: 3200 * time.Millisecond}
	for i, r := range p.requests {
		result.Samples = append(result.Samples, Sample{Index: i, StartedAt: r.Scheduled, WrittenAt: r.Scheduled + time.Millisecond, FinishedAt: finish[i], Outcome: outcomes[i]})
	}
	return p, result
}

func TestSummaryUsesLogicalOriginAndFirstCompletion(t *testing.T) {
	p, result := summaryFixture(t)
	summary, err := Summarize(p, result)
	if err != nil || !summary.MeasurementValid || len(summary.InvalidReasons) != 0 {
		t.Fatal(summary, err)
	}
	m := summary.Measurement
	if m.Scheduled != 4 || m.Started != 4 || m.RepeatedResults != 2 || m.UniqueBusinessResults != 2 || m.UniqueAcceptedOrders != 2 || m.UniqueTrades != 2 || m.NewOrdersFinishedWithinWindow != 1 || m.NewOrdersPerSecond != 0.5 {
		t.Fatal("warmup/retry/late completion inflated throughput", m)
	}
	want := Distribution{Count: 2, Min: 600 * time.Millisecond, P50: 600 * time.Millisecond, P95: 700 * time.Millisecond, P99: 700 * time.Millisecond, Max: 700 * time.Millisecond}
	if m.UniqueNewOrderScheduledLatency != want || m.RequestLatency.Count != 4 || m.RequestLatency.Max != 900*time.Millisecond {
		t.Fatalf("fast retry hid original scheduling delay: %+v", m)
	}
	if summary.Warmup.UniqueAcceptedOrders != 2 || summary.Warmup.UniqueTrades != 1 || m.GeneratorDropRate != 0 || m.TimeoutRate != 0 || m.OverloadRate != 0 {
		t.Fatal(summary)
	}
	if m.Intents[Duplicate] != 2 || m.Responses[Business] != 4 {
		t.Fatal("attempt classification was confused with unique results")
	}
	if m.UniqueMatchedOrders != 1 || m.TradesPerSecond != 1 || m.RequestLatencyByIntent[Duplicate].P99 != 100*time.Millisecond || m.RequestLatencyByClass[Business].Count != 4 {
		t.Fatal("trade and category latency accounting differs", m)
	}
	// Summarization must not sort/rewrite the caller's original raw samples.
	if result.Samples[3].FinishedAt != 2400*time.Millisecond || result.Samples[4].FinishedAt != 2100*time.Millisecond {
		t.Fatal("raw samples were mutated")
	}
}

func TestSummarySeparatesUnsentUnknownRejectionAndOverload(t *testing.T) {
	p, result := summaryFixture(t)
	result.Samples[2].Outcome = Outcome{Class: Overload, HTTPStatus: 429, Code: "QUEUE_FULL", Certainty: "NOT_ADMITTED"}
	result.Samples[3].Outcome = Outcome{Class: TransportTimeout, Certainty: "UNKNOWN"}
	result.Samples[4] = Sample{Index: 4, Local: LocalCapacity, StartedAt: -1, WrittenAt: -1, FinishedAt: 2 * time.Second}
	rejected := business(13, 0)
	rejected.Code, rejected.OrderStatus = string(d.InsufficientBalance), d.Rejected
	result.Samples[5].Outcome = rejected
	summary, err := Summarize(p, result)
	if err != nil {
		t.Fatal(err)
	}
	m := summary.Measurement
	if summary.MeasurementValid || !reflect.DeepEqual(summary.InvalidReasons, []string{"GENERATOR_MISSED_REQUESTS"}) || m.GeneratorDropRate != 0.25 || m.TimeoutRate != 1.0/3 || m.OverloadRate != 1.0/3 || m.UnknownLogicalCommands != 1 || m.UniqueBusinessRejections != 1 || m.UniqueAcceptedOrders != 0 || m.UniqueNewOrderScheduledLatency.Count != 0 {
		t.Fatal(summary)
	}
	// A later valid retry resolves uncertainty but is still only one new order.
	result.Samples[4] = Sample{Index: 4, StartedAt: 2 * time.Second, WrittenAt: -1, FinishedAt: 2100 * time.Millisecond, Outcome: business(12, 2)}
	summary, err = Summarize(p, result)
	if err != nil || !summary.MeasurementValid || summary.Measurement.UnknownLogicalCommands != 0 || summary.Measurement.UniqueAcceptedOrders != 1 || summary.Measurement.NewOrdersPerSecond != 0.5 {
		t.Fatal(summary, err)
	}
}

func TestSummaryCountsCancelsAndNoopsSeparately(t *testing.T) {
	p := scheduledPlan(t, 4, 500*time.Millisecond)
	target := p.requests[0].Command.Place.ClientOrderID
	cancel := d.Command{RunID: testRun, AccountID: p.requests[0].Command.AccountID, Kind: d.CancelOrder, Cancel: d.Cancel{CancelRequestID: "cancel", ClientOrderID: target}}
	p.requests[1] = request(cancel, Measure, Cancel, 1, 250*time.Millisecond)
	result := RunResult{Elapsed: 500 * time.Millisecond, Samples: []Sample{
		{Index: 0, StartedAt: 0, WrittenAt: -1, FinishedAt: 10 * time.Millisecond, Outcome: business(1, 0)},
		{Index: 1, StartedAt: 250 * time.Millisecond, WrittenAt: -1, FinishedAt: 260 * time.Millisecond, Outcome: business(2, 0)},
	}}
	result.Samples[1].Outcome.Code, result.Samples[1].Outcome.OrderStatus = string(d.AlreadyFilled), d.Filled
	summary, err := Summarize(p, result)
	if err != nil || summary.Measurement.UniqueSuccessfulCancels != 0 || summary.Measurement.UniqueBusinessResults != 2 || summary.Measurement.UniqueAcceptedOrders != 1 {
		t.Fatal(summary, err)
	}
	result.Samples[1].Outcome.Code, result.Samples[1].Outcome.OrderStatus = string(d.CancelSucceeded), d.Cancelled
	summary, err = Summarize(p, result)
	if err != nil || summary.Measurement.UniqueSuccessfulCancels != 1 || summary.Measurement.NewOrdersPerSecond != 2 || summary.Measurement.CancelsPerSecond != 2 {
		t.Fatal(summary, err)
	}
}

func TestSummaryRejectsCorruptOrInconsistentEvidence(t *testing.T) {
	if _, err := Summarize(&Plan{}, RunResult{}); err == nil {
		t.Fatal("empty unbuilt plan reported as a valid measurement")
	}
	for name, mutate := range map[string]func(*Plan, *RunResult){
		"missing sample": func(_ *Plan, r *RunResult) { r.Samples = r.Samples[1:] },
		"index":          func(_ *Plan, r *RunResult) { r.Samples[0].Index = 99 },
		"early start":    func(_ *Plan, r *RunResult) { r.Samples[1].StartedAt = 0 },
		"bad write time": func(_ *Plan, r *RunResult) { r.Samples[1].WrittenAt = 5 * time.Second },
		"missing finish": func(_ *Plan, r *RunResult) { r.Samples[0].FinishedAt = -1 },
		"short window": func(_ *Plan, r *RunResult) {
			r.Elapsed = 2500 * time.Millisecond
			r.Samples[5].FinishedAt = 2500 * time.Millisecond
		},
		"fake not sent":   func(_ *Plan, r *RunResult) { r.Samples[0].Local = LocalCapacity },
		"missing hash":    func(_ *Plan, r *RunResult) { r.Samples[0].Outcome.Fingerprint = "" },
		"mutable retry":   func(_ *Plan, r *RunResult) { r.Samples[2].Outcome.Fingerprint = fmt.Sprintf("%064x", 9) },
		"sequence reused": func(_ *Plan, r *RunResult) { r.Samples[1].Outcome.CommandSeq = r.Samples[0].Outcome.CommandSeq },
		"invalid status":  func(_ *Plan, r *RunResult) { r.Samples[0].Outcome.OrderStatus = "impossible" },
		"transport certainty": func(_ *Plan, r *RunResult) {
			r.Samples[0].Outcome = Outcome{Class: TransportFailure, Certainty: "NOT_ADMITTED"}
		},
		"hidden overload": func(_ *Plan, r *RunResult) {
			r.Samples[0].Outcome = Outcome{Class: ServerFailure, HTTPStatus: 429, Certainty: "NOT_ADMITTED"}
		},
		"missing class": func(_ *Plan, r *RunResult) { r.Samples[0].Outcome = Outcome{} },
	} {
		t.Run(name, func(t *testing.T) {
			p, r := summaryFixture(t)
			mutate(p, &r)
			if _, err := Summarize(p, r); err == nil {
				t.Fatal("corrupt evidence silently accepted")
			}
		})
	}
}

func TestSummaryInvalidResponseAndAbortedSamplesRemainVisible(t *testing.T) {
	p, result := summaryFixture(t)
	result.Samples[5].Outcome = Outcome{Class: InvalidResponse, HTTPStatus: 200, Certainty: "UNKNOWN", Detail: "truncated JSON"}
	summary, err := Summarize(p, result)
	if err != nil || summary.MeasurementValid || !reflect.DeepEqual(summary.InvalidReasons, []string{"INVALID_RESPONSES"}) || summary.Measurement.UnknownLogicalCommands != 1 {
		t.Fatal(summary, err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	result, err = Run(ctx, p, testRunOptions(), executorFunc(func(context.Context, Request) Execution { panic("must not execute") }))
	if err == nil {
		t.Fatal("canceled run was successful")
	}
	summary, err = Summarize(p, result)
	if err != nil || summary.MeasurementValid || summary.Warmup.Scheduled != 2 || summary.Measurement.Scheduled != 4 || summary.Measurement.LocalFailures[LocalCanceled] != 4 || summary.Measurement.UnknownLogicalCommands != 0 {
		t.Fatal(summary, err)
	}
}

func TestExactNearestRankQuantiles(t *testing.T) {
	var values []time.Duration
	for i := 100; i > 0; i-- {
		values = append(values, time.Duration(i))
	}
	if got := distribution(values); got != (Distribution{Count: 100, Min: 1, P50: 50, P95: 95, P99: 99, Max: 100}) {
		t.Fatal(got)
	}
	if distribution(nil) != (Distribution{}) || distribution([]time.Duration{7}) != (Distribution{Count: 1, Min: 7, P50: 7, P95: 7, P99: 7, Max: 7}) {
		t.Fatal("empty/singleton percentiles are ambiguous")
	}
}

func TestRunAndSummaryAgreeOnEveryCompletedRequest(t *testing.T) {
	p := scheduledPlan(t, 50, 100*time.Millisecond)
	result, err := Run(context.Background(), p, testRunOptions(), executorFunc(func(_ context.Context, request Request) Execution {
		return Execution{Outcome: business(d.Int(request.Index+1), 0), WrittenAt: time.Now()}
	}))
	if err != nil {
		t.Fatal(err)
	}
	summary, err := Summarize(p, result)
	if err != nil || !summary.MeasurementValid || summary.Measurement.UniqueAcceptedOrders != p.Count() || summary.Measurement.Scheduled != p.Count() || summary.Measurement.UniqueNewOrderScheduledLatency.Count != p.Count() {
		t.Fatal(summary, err)
	}
}
